import { notifications } from '@mantine/notifications';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi } from 'vitest';

import { NewGameForm } from '@/components/NewGameForm/NewGameForm';
import { Wrapper } from '@/tests/components/lib/common';
import { defaultInvitationDecision } from '@/tests/mocks/data/newGame';

const mockTriggerInvitations = vi.fn();

describe('NewGameForm', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        mockTriggerInvitations.mockResolvedValue(defaultInvitationDecision);
    });

    it('renders the form fields', () => {
        render(
            <Wrapper>
                <NewGameForm
                    onTriggerInvitations={mockTriggerInvitations}
                />
            </Wrapper>,
        );

        expect(screen.getByLabelText(/Override time check/i)).toBeInTheDocument();
        expect(screen.getByLabelText(/Custom message/i)).toBeInTheDocument();
        expect(screen.getByRole('button', { name: /Send invitations/i })).toBeInTheDocument();
    });

    it('submits the form and shows a ready notification', async () => {
        const user = userEvent.setup();
        const notificationUpdateSpy = vi.spyOn(notifications, 'update');

        render(
            <Wrapper>
                <NewGameForm
                    onTriggerInvitations={mockTriggerInvitations}
                />
            </Wrapper>,
        );

        await user.click(screen.getByLabelText(/Override time check/i));
        await user.type(screen.getByLabelText(/Custom message/i), 'Let us know early.');
        await user.click(screen.getByRole('button', { name: /Send invitations/i }));

        await waitFor(() => {
            expect(mockTriggerInvitations).toHaveBeenCalledWith({
                overrideTimeCheck: true,
                customMessage: 'Let us know early.',
            });
        });

        await waitFor(() => {
            expect(notificationUpdateSpy).toHaveBeenCalledWith(
                expect.objectContaining({
                    title: 'Invitations ready',
                    message: 'Invitations can be sent now.',
                    color: 'teal',
                }),
            );
        });
    });

    it('shows a skipped notification when status is not ready', async () => {
        const user = userEvent.setup();
        const notificationUpdateSpy = vi.spyOn(notifications, 'update');
        mockTriggerInvitations.mockResolvedValue({ status: 'skipped', reason: 'too-early' });

        render(
            <Wrapper>
                <NewGameForm onTriggerInvitations={mockTriggerInvitations} />
            </Wrapper>,
        );

        await user.click(screen.getByRole('button', { name: /Send invitations/i }));

        await waitFor(() => {
            expect(notificationUpdateSpy).toHaveBeenCalledWith(
                expect.objectContaining({
                    color: 'yellow',
                    title: 'Invitations skipped',
                    message: 'Skipped: too early',
                }),
            );
        });
    });

    it('shows a generic error message when the request fails with a non-Error value', async () => {
        const user = userEvent.setup();
        const notificationUpdateSpy = vi.spyOn(notifications, 'update');
        mockTriggerInvitations.mockRejectedValue('not an error object');

        render(
            <Wrapper>
                <NewGameForm onTriggerInvitations={mockTriggerInvitations} />
            </Wrapper>,
        );

        await user.click(screen.getByRole('button', { name: /Send invitations/i }));

        await waitFor(() => {
            expect(notificationUpdateSpy).toHaveBeenCalledWith(
                expect.objectContaining({
                    title: 'Error',
                    color: 'red',
                    message: 'Failed to check invitations.',
                }),
            );
        });
    });

    it('shows an error notification when the request fails', async () => {
        const user = userEvent.setup();
        const notificationUpdateSpy = vi.spyOn(notifications, 'update');
        mockTriggerInvitations.mockRejectedValue(new Error('Boom'));

        render(
            <Wrapper>
                <NewGameForm
                    onTriggerInvitations={mockTriggerInvitations}
                />
            </Wrapper>,
        );

        await user.click(screen.getByRole('button', { name: /Send invitations/i }));

        await waitFor(() => {
            expect(notificationUpdateSpy).toHaveBeenCalledWith(
                expect.objectContaining({
                    title: 'Error',
                    color: 'red',
                    message: 'Error: Boom',
                }),
            );
        });
    });
});

